package com.aditya.fefo.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="idempotency_keys",uniqueConstraints=@UniqueConstraint(columnNames={"idempotency_key","endpoint"})) public class IdempotencyKey { @Id private UUID id; @Column(name="idempotency_key") private String idempotencyKey; private String endpoint; @Column(name="request_hash") private String requestHash; @Column(name="response_status") private Integer responseStatus; @Column(name="response_body",columnDefinition="jsonb") private String responseBody; @Column(name="created_at") private Instant createdAt; @Column(name="expires_at") private Instant expiresAt; protected IdempotencyKey(){} public IdempotencyKey(String key,String endpoint,String hash,Instant expiresAt){this.id=UUID.randomUUID();this.idempotencyKey=key;this.endpoint=endpoint;this.requestHash=hash;this.expiresAt=expiresAt;this.createdAt=Instant.now();} public String getRequestHash(){return requestHash;} public Integer getResponseStatus(){return responseStatus;} public String getResponseBody(){return responseBody;} public void complete(int status,String body){responseStatus=status;responseBody=body;} }
